const body = $input.first().json.body || {};
const dealId = String(body.dealId || '').trim();
if (!dealId) return [{ json: { ok: false, statusCode: 400, body: { error: 'No dealId provided.' } } }];
return [{ json: { ok: true, dealId } }];

// Same gates as the app function: blocked deal stage first, then a
// missing [E] Order ID. Both short-circuit before any Eclipse call.
// The stage label comes from the dealstage property's options (the
// HubSpot node has no pipelines resource); options are matched by id.
const BLOCKED_STAGE_TOKENS = ['lost', 'delivered', 'invoiced', 'qualified', 'discovery'];
const deal = $('HubSpot: get deal').first().json;
const prop = $input.first().json;
const dealId = $('Validate').first().json.dealId;

if (deal.error || deal.objectFound === false) {
  return [{ json: { ok: false, statusCode: 500, body: { error: deal.error ? ('HubSpot deal fetch failed: ' + deal.error) : ('Deal ' + dealId + ' not found.') } } }];
}
const props = deal.properties || {};
const stageId = props.dealstage || null;
const options = Array.isArray(prop.options) ? prop.options : [];
const opt = options.find((o) => String(o.value) === String(stageId));
const stageLabel = opt ? opt.label : null;

const l = String(stageLabel || '').toLowerCase();
const token = stageLabel ? BLOCKED_STAGE_TOKENS.find((t) => l.includes(t)) : null;
if (token) {
  const displayStage = stageLabel || stageId || '(unknown)';
  return [{ json: { ok: false, statusCode: 200, body: { blocked: {
    reason: 'stage', stageLabel: displayStage,
    message: 'Cannot modify this order as it is in stage ' + displayStage,
  } } } }];
}
if (!props.e_sorder_id) {
  return [{ json: { ok: false, statusCode: 200, body: { blocked: { reason: 'missing_oid', message: 'Eclipse order ID missing' } } } }];
}
return [{ json: {
  ok: true,
  dealId,
  dealName: props.dealname || '',
  eclipseOrderId: props.e_sorder_id,
  latitude: parseFloat(props.latitude) || null,
  longitude: parseFloat(props.longitude) || null,
} }];

const r = $input.first().json;
if (r.error) {
  return [{ json: { ok: false, statusCode: 500, body: { error: 'HubSpot associations error: ' + r.error } } }];
}
const ids = [];
const results = Array.isArray(r.results) ? r.results : [];
for (const res of results) {
  for (const t of (res.to || [])) ids.push(String(t.toObjectId || t.id));
}
if (!ids.length) {
  // No line items: same empty payload the app function returned.
  return [{ json: { ok: false, statusCode: 200, body: {
    lineItems: [], productIds: [],
    fulfillmentOptions: { closestCombo: null, allBranchesWithStock: [] },
    branchMatrix: [],
  } } }];
}
return [{ json: { ok: true, ids: [...new Set(ids)] } }];

const r = $input.first().json;
if (r.error) {
  return [{ json: { ok: false, statusCode: 500, body: { error: 'HubSpot line items error: ' + r.error } } }];
}
const lineItems = (Array.isArray(r.results) ? r.results : []).map((row) => {
  const p = row.properties || {};
  return {
    id: row.id,
    name: p.name || 'Unknown Product',
    quantity: parseFloat(p.quantity) || 1,
    eclipseProductId: p.e_product_id_ || p.hs_sku || '',
    price: parseFloat(p.price) || 0,
  };
});
const missing = lineItems.filter((li) => !li.eclipseProductId);
if (missing.length) {
  const noun = missing.length === 1 ? 'line item' : 'line items';
  return [{ json: { ok: false, statusCode: 200, body: { blocked: {
    reason: 'missing_product_ids',
    missingItems: missing.map((li) => li.name || ('Line item ' + li.id)),
    message: missing.length + ' ' + noun + ' missing an Eclipse Product ID. Map every line item on the deal before placing the order.',
  } } } }];
}
const gate = $('Stage + OID gate').first().json;
const productIds = [...new Set(lineItems.map((i) => String(i.eclipseProductId)))];
return [{ json: { ok: true, lineItems, productIds, eclipseOrderId: gate.eclipseOrderId } }];

// Pricing inquiry needs a customer id; the deal only carries the order id.
// Eclipse SO Get keeps the bill-to per generation (generations[].billToId),
// so use the generation from the deal's [E] Order ID (S0920344.0001 → gen 1),
// falling back to the first generation.
const env = $input.first().json;
const order = (Array.isArray(env.results) ? env.results[0] : env) || {};
const gens = Array.isArray(order.generations) ? order.generations : [];
const li = $('Line item gate').first().json;
const oid = String(li.eclipseOrderId || '');
const genNo = oid.includes('.') ? Number(oid.split('.')[1]) : null;
const gen = gens.find((g) => Number(g.generationId) === genNo) || gens[0] || {};
const customerId = String(gen.billToId || gen.shipToId || '');
return [{ json: {
  customerId,
  productIds: li.productIds.join(','),
  orderError: env.error ? String(env.error) : (customerId ? '' : 'No billToId on Eclipse order ' + oid),
} }];

// Port of STEP 4-6 of eclipseInventoryLookup.js. Branch coordinates,
// distance math, the branch matrix, unavailable products and the
// closest-combination algorithm are carried over unchanged.
//
// Per-branch stock: the old function read
// /ProductInventoryInquiry → branchAvailableQuantity[{warehouse, warehouseQty}].
// The Eclipse node's pricing inquiry is used instead; its per-branch field
// is UNVERIFIED (expected stockInfo[{warehouse, warehouseQty}], which is
// what the product-inquiry page renders), so several shapes are accepted.
const BRANCH_COORDS = {
  "1":  { name: "Wichita",       lat: 37.6369, lng: -97.3503  },
  "2":  { name: "Grand Island",  lat: 40.8755, lng: -98.3492  },
  "3":  { name: "Yankton",       lat: 42.8943, lng: -97.4106  },
  "4":  { name: "El Reno",       lat: 35.5335, lng: -97.9549  },
  "5":  { name: "Grain Valley",  lat: 39.0189, lng: -94.2255  },
  "6":  { name: "Garden City",   lat: 37.9546, lng: -100.8354 },
  "7":  { name: "Caldwell",      lat: 43.6749, lng: -116.7025 },
  "8":  { name: "Evans",         lat: 40.3775, lng: -104.7214 },
  "9":  { name: "Brush",         lat: 40.2694, lng: -103.6214 },
  "12": { name: "Pasco",         lat: 46.2378, lng: -119.0906 },
  "14": { name: "Stockton",      lat: 37.9392, lng: -121.3115 },
  "15": { name: "Fresno",        lat: 36.6975, lng: -119.7423 },
  "16": { name: "Salinas",       lat: 36.6433, lng: -121.5898 },
  "17": { name: "Yuma",          lat: 32.6841, lng: -114.5683 },
};

function haversineKm(lat1, lng1, lat2, lng2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a = Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function parseBranchId(warehouseStr) {
  const s = String(warehouseStr || '').trim();
  if (/^\d+$/.test(s)) return s;
  const match = s.match(/^(\d+)\s*-/);
  return match ? match[1] : null;
}

function branchEntries(r) {
  const arr = r.branchAvailableQuantity || r.stockInfo || r.inventory || [];
  if (!Array.isArray(arr)) return [];
  return arr.map((e) => ({
    warehouse: String(e.warehouse || e.branch || e.branchName || e.branchId || ''),
    qty: Number(e.warehouseQty ?? e.availableQty ?? e.availableQuantity ?? e.quantity ?? e.qty ?? 0) || 0,
  }));
}

function findClosestCombination(sortedBranches, productIds, requiredQty) {
  const combo = [];
  const assignments = {};
  const remainingQty = {};
  for (const pid of productIds) {
    remainingQty[pid] = requiredQty[pid] || 1;
    assignments[pid] = [];
  }
  const pool = [...sortedBranches];
  while (Object.values(remainingQty).some((q) => q > 0)) {
    if (pool.length === 0) break;
    let bestIdx = -1;
    let bestTakeSum = 0;
    let bestBreakdown = null;
    for (let i = 0; i < pool.length; i++) {
      const b = pool[i];
      let takeSum = 0;
      const breakdown = {};
      for (const pid of productIds) {
        const need = remainingQty[pid];
        const have = b.products[pid] || 0;
        if (need > 0 && have > 0) {
          const take = Math.min(need, have);
          breakdown[pid] = take;
          takeSum += take;
        }
      }
      if (takeSum > bestTakeSum) {
        bestTakeSum = takeSum;
        bestIdx = i;
        bestBreakdown = breakdown;
      }
    }
    if (bestIdx === -1) break;
    const chosen = pool.splice(bestIdx, 1)[0];
    combo.push(chosen);
    for (const [pid, take] of Object.entries(bestBreakdown)) {
      remainingQty[pid] -= take;
      assignments[pid].push({ branchId: chosen.branchId, quantity: take });
    }
  }
  if (Object.values(remainingQty).some((q) => q > 0)) return null;
  const maxDistance = combo.length ? Math.max(...combo.map((b) => b.distanceKm)) : 0;
  return { branches: combo, maxDistance, assignments };
}

const gate = $('Stage + OID gate').first().json;
const li = $('Line item gate').first().json;
const lineItems = li.lineItems;
const productIds = li.productIds;
const custLat = gate.latitude;
const custLng = gate.longitude;
const pricing = $input.first().json;

// Inventory results keyed by product id
const failedProducts = [];
const stockByPid = {};
if (pricing.error) {
  const msg = String(pricing.error) + (pricing.message ? ': ' + JSON.stringify(pricing.message) : '');
  for (const pid of productIds) failedProducts.push({ productId: pid, error: msg });
} else {
  const results = Array.isArray(pricing.results) ? pricing.results : [];
  for (const r of results) {
    if (r && r.productId != null) stockByPid[String(r.productId)] = branchEntries(r);
  }
  for (const pid of productIds) {
    if (!stockByPid[pid]) failedProducts.push({ productId: pid, error: 'No inventory returned' });
  }
}

const branchMatrix = {};
for (const [branchId, coords] of Object.entries(BRANCH_COORDS)) {
  const distance = custLat !== null && custLng !== null
    ? haversineKm(custLat, custLng, coords.lat, coords.lng) : 9999;
  branchMatrix[branchId] = {
    branchId, branchName: branchId + ' - ' + coords.name,
    lat: coords.lat, lng: coords.lng,
    distanceKm: Math.round(distance * 10) / 10,
    products: {},
  };
}
for (const [pid, entries] of Object.entries(stockByPid)) {
  for (const entry of entries) {
    const branchId = parseBranchId(entry.warehouse);
    if (!branchId) continue;
    if (!branchMatrix[branchId]) {
      const rawName = entry.warehouse.replace(/^\d+\s*-\s*/, '').trim() || ('Branch ' + branchId);
      branchMatrix[branchId] = {
        branchId, branchName: branchId + ' - ' + rawName,
        lat: null, lng: null, distanceKm: 9999, products: {},
      };
    }
    branchMatrix[branchId].products[pid] = (branchMatrix[branchId].products[pid] || 0) + entry.qty;
  }
}
const sortedBranches = Object.values(branchMatrix).sort((a, b) => a.distanceKm - b.distanceKm);

const unavailableProducts = [];
const availableProductIds = [];
for (const pid of productIds) {
  const totalQty = sortedBranches.reduce((sum, b) => sum + (b.products[pid] || 0), 0);
  if (totalQty <= 0) {
    const item = lineItems.find((x) => String(x.eclipseProductId) === String(pid));
    unavailableProducts.push({ productId: pid, name: item ? item.name : ('Product ' + pid) });
  } else {
    availableProductIds.push(pid);
  }
}
const fulfillProductIds = availableProductIds.length > 0 ? availableProductIds : productIds;

const requiredQty = {};
for (const item of lineItems) {
  if (item.eclipseProductId) {
    requiredQty[item.eclipseProductId] = (requiredQty[item.eclipseProductId] || 0) + (item.quantity || 1);
  }
}
const closestCombo = findClosestCombination(sortedBranches, fulfillProductIds, requiredQty);
const allBranchesWithStock = sortedBranches.filter((b) =>
  fulfillProductIds.some((pid) => (b.products[pid] || 0) > 0));

return [{ json: { statusCode: 200, body: {
  lineItems,
  productIds: fulfillProductIds,
  unavailableProducts,
  failedProducts,
  deal: { eclipseOrderId: gate.eclipseOrderId || null, dealName: gate.dealName || '' },
  fulfillmentOptions: { closestCombo, allBranchesWithStock },
  branchMatrix: sortedBranches,
} } }];
